    eapply L5K.outside_cons_e; [evalEk' ZA Hag ltac:(clear - HV33l HV33r K3l K3r K5) | evalEk' ZA Hag ltac:(clear) | clear - HV33l HV33r K3l K3r K5 Hn1; lia |].
    apply L5K.outside_nil_e. }
  split. exact FRW.
  split. { intros i Hi Hn0 Hn1. apply FRW; rewrite ?BG.unsigned_lit by exact Hi; assumption. }
  apply L5K.nth_error_single in Hnth. subst ps.
  change (SR.ps_pc PliB.ps0) with 0x90118 in Hms. change (SR.ps_regs PliB.ps0) with (map (fun i => (i, nth i PliB.regs_out0 (ELit 0))) (seq 1 31)) in Hregs.
  change (SR.ps_cells PliB.ps0) with PliB.cells0 in Hcells.
  split. { exact Hms. }
  split. { intros j Hj. apply (BG.kept_regs E E' R R' PliB.regs0 PliB.regs_out0 48 KS_liB KS_liB_ok HR Hag Hregs j Hj). }
  split. { rewrite (BG.out_reg PliB.regs_out0 E' R' 10 Hregs) by (clear; lia). cbn [nth PliB.regs_out0]. first [reflexivity | wordP' ZA Hag]. }
  split. { rewrite (BG.out_reg PliB.regs_out0 E' R' 11 Hregs) by (clear; lia). cbn [nth PliB.regs_out0]. first [reflexivity | wordP' ZA Hag]. }
  eapply u64_of_KWord8a; [apply Hcells; apply (nth_error_In _ 0%nat); reflexivity | evalEk' ZA Hag ltac:(clear - HV33l HV33r K3l K3r K5) | evalEk' ZA Hag ltac:(clear) | clear; lia]. 
Qed.
