  split. { rewrite (BG.out_reg PliD.regs_out0 E' R' 10 Hregs) by (clear; lia). cbn [nth PliD.regs_out0]. first [reflexivity | wordP' ZA Hag]. }
  rewrite (BG.out_reg PliD.regs_out0 E' R' 11 Hregs) by (clear; lia). cbn [nth PliD.regs_out0]. first [reflexivity | wordP' ZA Hag]. 
