  exists fx' R' M', mem_grows M M'
    /\ (forall a : word, ~ (((V 33%nat) + 496) <= bv_unsigned a < ((V 33%nat) + 496) + 8) -> M' a = M a)
    /\ (forall i : Z, 0 <= i < 2 ^ 64 -> ~ (((V 33%nat) + 496) <= i < ((V 33%nat) + 496) + 8) -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i))
