  23 <= n < 2 ^ 26 -> 0 <= ptr < 2 ^ 64 ->
  getr R (PMK.reg 2) = Z_to_bv 64 sp -> getr R (PMK.reg 10) = Z_to_bv 64 o -> getr R (PMK.reg 11) = Z_to_bv 64 ptr -> getr R (PMK.reg 12) = Z_to_bv 64 n ->
