Lemma ddq_loop (n : nat) : forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (A' B' q : Z),
  ((Z.to_nat ((A' * 2 ^ 64 + B') / TEN19)) <= n)%nat ->
  getr R (reg 10) = Z_to_bv 64 0 -> getr R (reg 11) = Z_to_bv 64 ((B' + 8446744073709551616) mod 2 ^ 64) -> getr R (reg 12) = Z_to_bv 64 q ->
  getr R (reg 13) = Z_to_bv 64 TEN19 -> getr R (reg 14) = Z_to_bv 64 A' -> getr R (reg 15) = Z_to_bv 64 B' ->
  0 <= A' < 2 ^ 64 -> 0 <= B' < 2 ^ 64 -> 0 <= q -> q + (A' * 2 ^ 64 + B') / TEN19 < 2 ^ 64 -> (A' <> 0 \/ TEN19 <= B') ->
  L5.img_clear M 65536 814272 ->
  exists fx' R', msteps RSEGS (st fx R 0x440d4 M) (st fx' R' 0x440f4 M)
    /\ (forall x, In x KSQ -> getr R' (reg x) = getr R (reg x))
    /\ getr R' (reg 10) = Z_to_bv 64 0 /\ getr R' (reg 12) = Z_to_bv 64 (q + (A' * 2 ^ 64 + B') / TEN19).
Proof.
