Lemma div1i_run (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (S ra fb rb v0 v1 : Z) :
  getr R (reg 1) = Z_to_bv 64 ra -> getr R (reg 2) = Z_to_bv 64 S -> getr R (reg 10) = Z_to_bv 64 (S + 72) -> getr R (reg 11) = Z_to_bv 64 (S + 8) ->
  getr R (reg 12) = Z_to_bv 64 (S + 72) -> getr R (reg 13) = Z_to_bv 64 (S + 40) -> getr R (reg 14) = Z_to_bv 64 1 ->
  0 <= ra < 2 ^ 64 -> 140735332483552 <= S <= 140737488355328 -> S mod 16 = 0 ->
  L5.writable RSEGS M (S - 480) 480 -> L5.img_clear M 65536 814272 -> L5.defined M (S - 480) 480 -> L5.writable RSEGS M (S + 8) 96 ->
  L5.u8_at RSEGS M (S + 8) 0 -> L5.u64_at RSEGS M (S + 16) 1 -> L5.u64_at RSEGS M (S + 24) 10000000000000000000 -> L5.u64_at RSEGS M (S + 32) 0 ->
  L5.u8_at RSEGS M (S + 40) rb -> L5.u64_at RSEGS M (S + 48) 0 -> L5.u64_at RSEGS M (S + 56) 0 -> L5.u64_at RSEGS M (S + 64) 0 ->
  0 <= rb <= 255 -> Z.testbit rb 0 = false ->
  L5.u8_at RSEGS M (S + 72) fb -> L5.u64_at RSEGS M (S + 80) 2 -> L5.u64_at RSEGS M (S + 88) v0 -> L5.u64_at RSEGS M (S + 96) v1 ->
  0 <= fb <= 255 -> Z.testbit fb 0 = false -> 0 <= v0 < 2 ^ 64 -> 1 <= v1 <= 2 ^ 30 ->
  exists fx' R' M', msteps RSEGS (st fx R 0x42450 M) (st fx' R' 0x42a18 M') /\ mem_grows M M'
    /\ (forall i : Z, 0 <= i < 2 ^ 64 -> ~ (S - 480 <= i < S - 480 + 480) -> ~ (S + 8 <= i < S + 8 + 96) -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i))
    /\ (forall x, In x KSD -> getr R' (reg x) = getr R (reg x))
    /\ L5.u8_at RSEGS M' (S + 40) (Z.lor (Z.land rb 253) (Z.land fb 2))
    /\ L5.u64_at RSEGS M' (S + 48) (if (v1 * 2 ^ 64 + v0) mod TEN19 =? 0 then 0 else 1)
    /\ L5.u64_at RSEGS M' (S + 56) ((v1 * 2 ^ 64 + v0) mod TEN19) /\ L5.u64_at RSEGS M' (S + 64) 0
    /\ L5.u8_at RSEGS M' (S + 72) (Z.lor (Z.land fb 253) ((2 * (Z.lxor 0 (Z.land fb 2) / 2)) mod 2 ^ 64))
    /\ L5.u64_at RSEGS M' (S + 80) 1 /\ L5.u64_at RSEGS M' (S + 88) ((v1 * 2 ^ 64 + v0) / TEN19) /\ L5.u64_at RSEGS M' (S + 96) v1
    /\ L5.u8_at RSEGS M' (S + 8) 0 /\ L5.u64_at RSEGS M' (S + 16) 1 /\ L5.u64_at RSEGS M' (S + 24) 10000000000000000000 /\ L5.u64_at RSEGS M' (S + 32) 0.
Proof.
